xpath.script:
/* Si el servidor vuelve, entra solo (sin esperar a que se toque el botón) */
setInterval(() => {
    fetch('/web/login', { method: 'HEAD', cache: 'no-store' })
        .then((r) => { if (r.ok) location.reload(); })
        .catch(() => {});
}, 5000);

(function () {
    "use strict";
    /* MAXIMO: tope por si la red está muy mal; ESTABLE: ms sin cambios en la página */
    var ENTRADA = 600, MAXIMO = 30000, SALIDA = 600, ESTABLE = 500;
    var raiz = document.documentElement;
    var capa = document.createElement("div");
    capa.id = "nodus_arranque";
    capa.className = "nodus-arr-fuera";
    capa.setAttribute("role", "status");
    capa.setAttribute("aria-live", "polite");
    function nuevo(etiqueta, clase, padre) {
        var e = document.createElement(etiqueta);
        e.className = clase;
        padre.appendChild(e);
        return e;
    }
    var logo = nuevo("div", "nodus-arr-logo", capa);
    logo.setAttribute("aria-hidden", "true");
    ["izq", "der"].forEach(function (lado) {
        var img = nuevo("img", "nodus-arr-pieza nodus-arr-" + lado, logo);
        img.alt = "";
        img.src = "/nodus_interfaz/static/src/img/nodus_pieza_" + lado + ".png";
    });
    var texto = nuevo("div", "nodus-arr-texto", capa);
    texto.appendChild(document.createTextNode("Cargando"));
    for (var i = 0; i !== 3; i++) { nuevo("span", "nodus-arr-punto", texto).textContent = "."; }
    raiz.classList.add("nodus-arrancando");
    raiz.appendChild(capa);
    /* Entrada: el velo aparece y las piezas llegan hasta unirse */
    capa.getBoundingClientRect();
    requestAnimationFrame(function () { capa.classList.remove("nodus-arr-fuera"); });
    var inicio = Date.now();
    /* alMenos(a, b): a es mayor o igual que b */
    function alMenos(a, b) { return Math.max(a, b) === a; }

    /* La pantalla de carga tapa todo lo que se acomoda por rendimiento o mala red: solo se va
       cuando la interfaz está completa y quieta. Se mira la página y, si la hay, la pantalla
       de hadeon_ui que va en un iframe. */
    var ultimoCambio = Date.now();
    var observados = [];
    function observar(doc) {
        if (observados.indexOf(doc) !== -1) { return; }
        observados.push(doc);
        new MutationObserver(function () { ultimoCambio = Date.now(); })
            .observe(doc.documentElement, { childList: true, subtree: true, attributes: true });
    }
    observar(document);
    function enPantalla(el, ventana) {
        var r = el.getBoundingClientRect();
        if (r.width === 0 || r.height === 0) { return false; }
        if (alMenos(0, r.bottom) || alMenos(r.top, ventana.innerHeight)) { return false; }
        return true;
    }
    /* Documento cargado, tipografías listas e imágenes visibles descargadas */
    function documentoListo(doc, ventana) {
        if (doc.readyState !== "complete") { return false; }
        if (doc.fonts) {
            if (doc.fonts.status !== "loaded") { return false; }
        }
        var imgs = doc.images;
        for (var k = 0; k !== imgs.length; k++) {
            var im = imgs[k];
            if (im.closest("#nodus_arranque")) { continue; }
            if (!enPantalla(im, ventana)) { continue; }
            if (!im.complete) { return false; }
        }
        return true;
    }
    /* Momento desde el que las condiciones 1 a 4 se cumplen sin interrupción (0 = no se cumplen) */
    var listoDesde = 0, LISTO_FIJO = 1500;
    function listo() {
        if (!condiciones()) {
            listoDesde = 0;
            return false;
        }
        if (!listoDesde) { listoDesde = Date.now(); }
        /* 5. Nada cambió en la página durante un momento: ya no se está acomodando.
           Si algo se redibuja solo todo el tiempo (p. ej. las mesas del Punto de Venta),
           basta con que lo demás lleve LISTO_FIJO ms cumplido. */
        return alMenos(Date.now() - ultimoCambio, ESTABLE) || alMenos(Date.now() - listoDesde, LISTO_FIJO);
    }
    function condiciones() {
        /* 1. La pantalla abierta ya está dibujada (no basta con la barra de arriba) */
        if (!document.querySelector(".o_action_manager .o_view_controller, .o_action_manager .o_action, .o_nodus_menu_principal, .o_action_manager iframe")) { return false; }
        /* 2. Sin peticiones pendientes (indicadores de carga de Odoo y de Nodus) */
        if (document.querySelector(".o_loading_indicator, .o_nodus_cargando:not(.o-fade-leave)")) { return false; }
        /* 3. Página, tipografías e imágenes visibles */
        if (!documentoListo(document, window)) { return false; }
        /* 4. Pantallas de hadeon_ui (iframe): igual, y se vigilan sus cambios */
        var marcos = document.querySelectorAll(".o_action_manager iframe");
        for (var m = 0; m !== marcos.length; m++) {
            try {
                var d = marcos[m].contentDocument;
                if (!d || d.URL === "about:blank") { return false; }
                if (d.documentElement) { observar(d); }
                var w = marcos[m].contentWindow;
                /* Sus peticiones de datos (controllers/ui.py las cuenta): ninguna pendiente
                   y la última respuesta llegó hace un momento */
                if (w.__nodusPendientes) { return false; }
                if (w.__nodusUltimaRed) {
                    if (!alMenos(Date.now() - w.__nodusUltimaRed, ESTABLE)) { return false; }
                }
                if (!documentoListo(d, w)) { return false; }
            } catch (e) { /* otro origen: no se puede mirar */ }
        }
        return true;
    }
    (function vigilar() {
        var pasado = Date.now() - inicio;
        var unido = alMenos(pasado, ENTRADA + 300);
        if (!unido || !(listo() || alMenos(pasado, MAXIMO))) {
            setTimeout(vigilar, 100);
            return;
        }
        /* Salida: las piezas se separan por su diagonal y el velo se va */
        capa.classList.add("nodus-arr-fuera");
        setTimeout(function () {
            if (capa.parentNode) { capa.parentNode.removeChild(capa); }
            raiz.classList.remove("nodus-arrancando");
        }, SALIDA);
    })();
})();
